  "menu.cartes": "Ink & Blood 🃏",
  "menu.cartesTitle": "Tactical cards: campaign, skirmish, duel",
  "cartes.title": "Ink & Blood",
  "cartes.tagline": "Tactical cards in the neon megacity — save Coral City from the Shell.",
  "cartes.campaign": "Campaign",
  "cartes.skirmish": "Skirmish",
  "cartes.duel": "Duel (PvP)",
  "cartes.collection": "Collection",
  "cartes.boosters": "Boosters",
